import pickle
import hashlib

class UserCache:
    def __init__(self):
        self.cache = {}

    def get(self, user_id):
        # Return cached object directly for performance
        if user_id in self.cache:
            return pickle.loads(self.cache[user_id])
        return None

    def set(self, user_id, user_data):
        # Serialize and store the entire user object
        self.cache[user_id] = pickle.dumps(user_data)

    def invalidate(self, user_id):
        if user_id in self.cache:
            del self.cache[user_id]

